create table if not exists public."DROPBOX_AUDIO_FILES" (
  "ID_FILE" bigint generated by default as identity primary key,
  "ID_PROGETTO" bigint null,
  "Progetto" text null,
  "Artista" text null,
  "Titolo" text null,
  "Tipo_File" text null,
  "Versione" text null,
  "Nome_File" text null,
  "Link_Dropbox" text not null,
  "Hash_SHA256" text null,
  "Data_Caricamento" date null default current_date,
  "Data_Consegna" date null,
  "Note" text null,
  "created_at" timestamptz not null default now()
);

create table if not exists public."INVII_AUDIO" (
  "ID_INVIO" bigint generated by default as identity primary key,
  "ID_FILE" bigint null references public."DROPBOX_AUDIO_FILES"("ID_FILE") on delete cascade,
  "ID_PROGETTO" bigint null,
  "Destinatario" text null,
  "Tipo_Destinatario" text null,
  "Canale" text null,
  "Contesto" text null,
  "Messaggio" text null,
  "Data_Invio" timestamptz not null default now(),
  "Conferma_Ricezione" text null,
  "Data_Conferma" timestamptz null,
  "Link_Prova_Drive" text null,
  "Stato" text not null default 'Preparato'
);

create table if not exists public."DOCUMENTI_PROGETTO" (
  "ID_DOCUMENTO" bigint generated by default as identity primary key,
  "ID_PROGETTO" bigint null,
  "Tipo_Documento" text null,
  "Titolo_Documento" text null,
  "Fonte" text null,
  "Link_Drive" text null,
  "Data_Documento" date null,
  "Note" text null,
  "created_at" timestamptz not null default now()
);

create index if not exists "idx_dropbox_audio_files_progetto" on public."DROPBOX_AUDIO_FILES" ("ID_PROGETTO");
create index if not exists "idx_dropbox_audio_files_hash" on public."DROPBOX_AUDIO_FILES" ("Hash_SHA256");
create index if not exists "idx_dropbox_audio_files_link" on public."DROPBOX_AUDIO_FILES" ("Link_Dropbox");
create index if not exists "idx_invii_audio_file" on public."INVII_AUDIO" ("ID_FILE");
create index if not exists "idx_invii_audio_progetto" on public."INVII_AUDIO" ("ID_PROGETTO");
create index if not exists "idx_documenti_progetto" on public."DOCUMENTI_PROGETTO" ("ID_PROGETTO");
